import{_ as a,o as e,c as s,a4 as i}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20260422223840718.PiNlGq49.png",p="/assets/image-20260422223721332.CEGcEoBD.png",l="/assets/image-20260422143148278.DTbcJt1w.png",c="/assets/image-20260422143136199.Dy8vVRGk.png",r="/assets/image-20260422151001649.BoZcqD4L.png",o="/assets/image-20260422151503681.C2IxqnXu.png",w="/assets/image-20260422152950101.DmCxcTW0.png",u="/assets/image-20260422152935857.zPP-_0t9.png",g="/assets/image-20260422153648335.D-C55Gby.png",d="/assets/image-20260422225831632.B6NUeatG.png",h="/assets/image-20260404153811993.DCT8eByA.png",f=JSON.parse('{"title":"码道 安装  jiuwenclaw","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/码道安装jiuwenclaw/码道安装jiuwenclaw.md","filePath":"AI人工智能/码道安装jiuwenclaw/码道安装jiuwenclaw.md","lastUpdated":1776870350000,"__rawMarkdown":"# 码道 安装  jiuwenclaw\\n\\n## 官网\\n\\n> https://gitcode.com/openJiuwen/jiuwenclaw\\n>\\n> https://www.openjiuwen.com/\\n\\n## 什么是码道\\n\\n![](assets/image-20260422223840718.png)\\n\\n码道（CodeArts）是华为云于2026年2月26日发布的代码智能体公测版，定位为面向开发者和企业的工程化智能编码解决方案。\\n\\n\\n\\n## 什么是 jiuwenclaw\\n\\n![](assets/image-20260422223721332.png)\\n\\nopenJiuwen作为开源Agent平台，致力于提供灵活、强大且易用的AI Agent开发与运行能力。\\n\\n基于该平台，开发者可快速构建处理各类简单或复杂任务的AI Agent，实现多Agent协同交互，高效开发生产级可靠AI Agent；\\n\\n并助力企业与个人快速搭建AI Agent系统或平台，推动商用级Agentic AI技术广泛应用与落地。\\n\\n---\\n\\n\\n\\nJiuwenClaw 的核心使命是「懂你所想，自主演进」。\\n\\n针对你的各种复杂输入场景，如任务追加、打断、修改等，它就是懂你的贴身任务管家，将你的各类需求排出优先级，并有条不紊\\n\\n地完成；\\n\\n同时它也能在你身边自主演进，当你对它表达不满或运行出错时，它会根据你的反馈自动调整相应技能，全心全意为你服务。\\n\\n在连接渠道方面，JiuwenClaw 已实现鸿蒙小艺、飞书 Channel 的无缝接入，并将持续拓展至更多元平台。无论是进行复杂代码编\\n\\n写、寻求即时的技术支持，还是管理日程与信息流，JiuwenClaw 都能让你从任何地方、以最熟悉的方式，唤出一个始终在线、数据\\n\\n自主的专属 AI 助理。\\n\\n\\n\\n## 安装jiuwenclaw\\n\\n浏览**jiuwenclaw**文档\\n\\n![](assets/image-20260422143148278.png)\\n\\n\\n打开码道，直接复制以下安装和启动的命令到码道的对话框中，进行安装。\\n\\n![](assets/image-20260422143136199.png)\\n\\n---\\n\\n**等待安装**\\n\\n![](assets/image-20260422151001649.png)\\n\\n---\\n\\n## 初始化 jiuwenclaw\\n\\n在终端中输入命令进行初始化（只需要执行一次）：\\n\\n```\\njiuwenclaw-init\\n```\\n\\n然后jiuwenclaw会询问你语言的偏向，中文、英文等。\\n\\n![](assets/image-20260422151503681.png)\\n\\n## 启动jiuwenclaw\\n\\n初始化完毕后，可以在终端中输入命令，启动jiuwenclaw\\n\\n```\\njiuwenclaw-start\\n```\\n\\n![](assets/image-20260422152950101.png)\\n\\n## 使用jiuwenclaw\\n\\n当服务启动后，可以直接在浏览器中打开地址 `http://localhost:5173` 进行对话\\n\\n![](assets/image-20260422152935857.png)\\n\\n## 配置apikey\\n\\n正常情况下，**jiuwenclaw**的运作还需要提供提供兼容OpenAI的大模型，这里万少使用了**阿里百炼**的模型。\\n\\n按照表单填写好字段内容即可。\\n\\n![](assets/image-20260422153648335.png)\\n\\n## 成功\\n\\n继续回到对话窗口，输入你好，看到有回应表示 jiuwenclaw安装已经成功了。\\n\\n\\n\\n\\n\\n## 配置地址\\n\\njiuwenclaw默认的配置地址在\\n\\n`C:\\\\Users\\\\用户\\\\.jiuwenclaw`\\n\\n目录结构如下：\\n\\n```\\n   .agent_teams/    代理团队数据，包含团队数据库（team.db）及各个代理团队的配置\\n   .checkpoint/     检查点数据，存储 checkpoint.db 等会话快照/恢复点\\n   .codeartsdoer/   CodeArts Doer 相关缓存和配置\\n   .git/            Git 版本控制仓库目录\\n   .logs/           系统/服务日志存放目录（如 agent_server.log、gateway.log 等）\\n   agent/           代理工作目录，包含工作空间（jiuwenclaw_workspace）和会话数据\\n   config/          项目配置目录，存放 config.yaml、环境变量（.env）和规则文件\\n   logs/            额外的日志存储目录（与 .logs/ 类似，可能是不同组件输出）\\n   .gitignore       Git 忽略规则文件\\n```\\n\\n当然，大部分情况下，你可以在网页上配置。\\n\\n![](assets/image-20260422225831632.png)\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n------\\n\\n\\n\\n万少建立了一个专门讨论AI的微信群，大家可以互相交流和分享关于AI生态的资讯消息。\\n\\n目前人已经超过200人了，私聊我进群。\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/image-20260404153811993.DCT8eByA.png)"}'),m={name:"AI人工智能/码道安装jiuwenclaw/码道安装jiuwenclaw.md"};function b(j,n,_,A,k,v){return e(),s("div",null,[...n[0]||(n[0]=[i("",58)])])}const q=a(m,[["render",b]]);export{f as __pageData,q as default};
